window.DE_CHUNKS=window.DE_CHUNKS||[];window.DE_CHUNKS.push([{"id":504,"unit":5,"q":"Full adder has____","k":"A","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":505,"unit":5,"q":"half adder is an example of-","k":"A","s":["Half-adder: Sum=A⊕B, Carry=AB.","Truth table (A,B → S,C): 00→00, 01→10, 10→10, 11→01."]},{"id":506,"unit":5,"q":"How many full adders are needed to add two 4-bit numbers with a parallel adders?","k":"B","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":507,"unit":5,"q":"The logic diagram shown in the figure performs the function of building block","k":"A","s":["Correct option: A.","This matches the answer key in the supplied practice book."]},{"id":508,"unit":5,"q":"Two binary digits are applied to input of two input Ex-or gate. The output of the logic can generate","k":"C","s":["Correct option: C.","This matches the answer key in the supplied practice book."]},{"id":509,"unit":5,"q":"Two binary digits are applied to the input of two input AND gate. The output of the logic can generate","k":"B","s":["Correct option: B.","This matches the answer key in the supplied practice book."]},{"id":510,"unit":5,"q":"Number of half and full adder required to construct a sixty four bit binary adder would be","k":"A","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":511,"unit":5,"q":"A full substractor can be constructed from two half substractor and one _____________","k":"A","s":["Correct option: A.","This matches the answer key in the supplied practice book."]},{"id":512,"unit":5,"q":"A full adder can be constructed from two half adder and one ______","k":"A","s":["Half adder 1: S1=A⊕B, C1=AB.","Half adder 2: S=S1⊕Cin, C2=S1·Cin.","Cout=C1+C2=AB+Cin(A⊕B).","Thus two half adders and one OR gate form a full adder."]},{"id":513,"unit":5,"q":"What are the advantages of parallel adders over serial adders? Two 4-bit binary numbers (1011 and 1111) are applied to a 4-bit parallel adder. The carry input is 1. What are the values for the sum and carry output?","k":"","s":["Serial adder uses one full adder repeatedly, one bit pair per clock: less hardware but slower.","Parallel adder uses one adder stage per bit so all bit positions work together: faster but more hardware."]},{"id":514,"unit":5,"q":"Design Truth Table and give Boolean function for Full-Subtractor circuit and implement it using half subtractor and gates.","k":"","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":515,"unit":5,"q":"Which of the following statements is/are not correct? 1) A half-adder is an arithmetic circuit that adds two binary digits. 2) A half-subtractor is an arithmetic circuit that subtracts two binary digits. 3) A full-subtractor is an arithmetic circuit that subtracts two binary digits along with borrow bit. 4) A full-adder is an arithmetic circuit that adds one binary digit and carry bit.","k":"B","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":516,"unit":5,"q":"Which of the following is correct Boolean function of sum and carry of Full adder, the inputs are A, B and C (internal carry)?","k":"C","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":517,"unit":5,"q":"Which of the following Boolean function of difference and borrow out (Bout) of full subtractor circuit, if the inputs are A, B and C (previous borrow)?B 1 D = A XOR B XOR C, Bout = A’B + AC + B’C’ D = A XOR B XOR C, Bout = A’B + A’C + BC D = A XOR B XOR C, Bout = A’B + A’C + B’C D = A XOR B XOR C, Bout = AB + AC + BC","k":"","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":518,"unit":5,"q":"The logic diagram shown in the following figure performs the function of a very common arithmetic building block. Identify the logic function.","k":"A","s":["Correct option: A.","This matches the answer key in the supplied practice book."]},{"id":519,"unit":5,"q":"In BCD addition, 0110 is required to be added to the sum for getting the correct result, if -","k":"D","s":["Add the two valid BCD digits with a 4-bit binary adder.","Correction condition: K = Cout + S3S2 + S3S1. If K=1, add 0110 to the first sum.","The corrected lower nibble is the units BCD digit and the carry is the tens digit."]},{"id":520,"unit":5,"q":"Design the digital circuit that adds (8)BCD with (7)BCD in parallel and produces a sum digit also in BCD format. Show the appropriate circuit diagram and steps that describe the BCD addition process.","k":"","s":["Decimal addition: 8 + 7 = 15.","BCD result = 0001 0101.","If the first 4-bit sum is greater than 1001 or Cout=1, add 0110 to correct it to BCD."]}]);